import {
  Component,
  Input,
  Output,
  EventEmitter,
  AfterViewInit,
  OnChanges,
  SimpleChanges,
  ViewChildren,
  QueryList,
  ElementRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';

export type AccordionVariant = 'default' | 'bordered' | 'separated';
export type AccordionSize = 'sm' | 'md' | 'lg';
export type AccordionType = 'single' | 'multiple';

export interface AccordionItem {
  value: string;
  label: string;
  content?: string;
  disabled?: boolean;
}

let accordionUid = 0;

@Component({
  selector: 'app-accordion',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './accordion.component.html',
  styleUrls: ['./accordion.component.css'],
})
export class AccordionComponent implements AfterViewInit, OnChanges {
  @Input() items: AccordionItem[] = [];
  @Input() type: AccordionType = 'single';
  @Input() value?: string | string[];
  @Input() defaultValue?: string | string[];
  @Input() collapsible = true;
  @Input() variant: AccordionVariant = 'default';
  @Input() size: AccordionSize = 'md';

  @Output() valueChange = new EventEmitter<string | string[]>();

  @ViewChildren('triggerEl') triggers!: QueryList<ElementRef<HTMLButtonElement>>;

  readonly rootId = `accordion-${++accordionUid}`;
  internalValue?: string | string[];

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['value'] && changes['value'].currentValue !== undefined) {
      this.internalValue = changes['value'].currentValue;
    }
  }

  ngAfterViewInit(): void {
    if (this.internalValue === undefined) {
      this.internalValue = this.value ?? this.defaultValue;
    }
  }

  get currentValue(): string | string[] | undefined {
    return this.value ?? this.internalValue;
  }

  private get openSet(): Set<string> {
    const v = this.currentValue;
    if (v == null) return new Set<string>();
    return new Set<string>(Array.isArray(v) ? v : [v]);
  }

  get rootClass(): string {
    return ['accordion-root', `variant-${this.variant}`, `size-${this.size}`].join(' ');
  }

  isOpen(item: AccordionItem): boolean {
    return this.openSet.has(item.value);
  }

  triggerId(item: AccordionItem): string {
    return `${this.rootId}-trigger-${item.value.replace(/[^a-zA-Z0-9_-]/g, '_')}`;
  }

  contentId(item: AccordionItem): string {
    return `${this.rootId}-content-${item.value.replace(/[^a-zA-Z0-9_-]/g, '_')}`;
  }

  toggle(item: AccordionItem): void {
    if (item.disabled) return;
    const open = this.openSet;
    if (this.type === 'multiple') {
      const next = new Set(open);
      if (next.has(item.value)) next.delete(item.value);
      else next.add(item.value);
      this.setValue(Array.from(next));
      return;
    }
    if (open.has(item.value)) {
      this.setValue(this.collapsible ? '' : item.value);
    } else {
      this.setValue(item.value);
    }
  }

  private setValue(next: string | string[]): void {
    if (this.value === undefined) this.internalValue = next;
    this.valueChange.emit(next);
  }

  onKeydown(event: KeyboardEvent, item: AccordionItem): void {
    let nextValue: string | null = null;
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      nextValue = this.moveFocus(item.value, 1);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      nextValue = this.moveFocus(item.value, -1);
    } else if (event.key === 'Home') {
      event.preventDefault();
      nextValue = this.focusEdge('first');
    } else if (event.key === 'End') {
      event.preventDefault();
      nextValue = this.focusEdge('last');
    }
    void nextValue;
  }

  private enabledOrder(): string[] {
    return this.items.filter((i) => !i.disabled).map((i) => i.value);
  }

  private focusByValue(value: string): void {
    const enabled = this.items.filter((i) => !i.disabled);
    const enabledIdx = enabled.findIndex((i) => i.value === value);
    if (enabledIdx < 0) return;
    const allIdx = this.items.findIndex((i) => i.value === value);
    this.triggers.toArray()[allIdx]?.nativeElement?.focus();
  }

  private moveFocus(current: string, direction: 1 | -1): string | null {
    const order = this.enabledOrder();
    if (order.length === 0) return null;
    const idx = order.indexOf(current);
    const nextIdx = idx === -1 ? 0 : (idx + direction + order.length) % order.length;
    const next = order[nextIdx];
    this.focusByValue(next);
    return next;
  }

  private focusEdge(edge: 'first' | 'last'): string | null {
    const order = this.enabledOrder();
    if (order.length === 0) return null;
    const next = edge === 'first' ? order[0] : order[order.length - 1];
    this.focusByValue(next);
    return next;
  }
}

import { Component, Input } from '@angular/core';
import { CommonModule } from '@angular/common';

export interface BreadcrumbItem {
  label: string;
  href?: string;
}

type DisplayItem = BreadcrumbItem & { ellipsis?: boolean };

@Component({
  selector: 'app-breadcrumb',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './breadcrumb.component.html',
  styleUrls: ['./breadcrumb.component.css'],
})
export class BreadcrumbComponent {
  @Input() items: BreadcrumbItem[] = [];
  @Input() separator = '/';
  @Input() maxItems = 0;
  @Input() size: 'sm' | 'md' | 'lg' = 'md';

  get display(): DisplayItem[] {
    const items = this.items;
    if (this.maxItems && this.maxItems >= 2 && items.length > this.maxItems) {
      return [
        items[0],
        { label: '…', ellipsis: true },
        ...items.slice(items.length - (this.maxItems - 1)),
      ];
    }
    return items;
  }
}

import {
  Component,
  Input,
  Output,
  EventEmitter,
  HostListener,
  ElementRef,
  ViewChild,
  ViewChildren,
  QueryList,
  AfterViewInit,
  OnDestroy,
  Renderer2,
  Inject,
  PLATFORM_ID,
} from '@angular/core';
import { CommonModule, isPlatformBrowser } from '@angular/common';
import { computePosition, autoUpdate, offset, flip, shift, type Placement } from '@floating-ui/dom';

export type DropdownMenuSize = 'sm' | 'md' | 'lg';
export type DropdownMenuVariant = 'default' | 'minimal';

export interface DropdownMenuItemModel {
  value: string;
  label: string;
  disabled?: boolean;
  separatorBefore?: boolean;
}

let menuIdCounter = 0;

@Component({
  selector: 'app-dropdown-menu',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './dropdownmenu.component.html',
  styleUrls: ['./dropdownmenu.component.css'],
})
export class DropdownMenuComponent implements AfterViewInit, OnDestroy {
  private _isOpen = false;
  private isViewInit = false;

  @Input()
  get open(): boolean {
    return this._isOpen;
  }
  set open(value: boolean) {
    const prev = this._isOpen;
    this._isOpen = value;
    if (prev !== value) {
      this.handleOpenStateChange(value);
    }
  }

  isPositioned = false;
  readonly contentId = `menu-content-${++menuIdCounter}`;

  @Input() triggerLabel = 'Open';
  @Input() items: DropdownMenuItemModel[] = [];
  @Input() placement: Placement = 'bottom-start';
  @Input() variant: DropdownMenuVariant = 'default';
  @Input() size: DropdownMenuSize = 'md';
  @Input() closeOnSelect = true;
  @Input() className = '';

  @Output() openChange = new EventEmitter<boolean>();
  @Output() select = new EventEmitter<string>();

  @ViewChild('triggerRef') triggerRef?: ElementRef<HTMLElement>;
  @ViewChild('contentRef') contentRef?: ElementRef<HTMLElement>;
  @ViewChildren('itemRef') itemRefs!: QueryList<ElementRef<HTMLButtonElement>>;

  private cleanupFloating?: () => void;
  private contentMoved = false;

  constructor(
    private renderer: Renderer2,
    @Inject(PLATFORM_ID) private platformId: Object,
  ) {}

  ngAfterViewInit() {
    this.isViewInit = true;
    if (this.open) {
      this.initFloating();
    }
  }

  ngOnDestroy() {
    this.destroyFloating();
  }

  private handleOpenStateChange(isOpen: boolean) {
    if (!this.isViewInit) return;
    if (isOpen) {
      setTimeout(() => {
        this.initFloating();
        this.focusFirstItem();
      }, 0);
    } else {
      this.destroyFloating();
    }
  }

  get contentClasses(): string {
    return ['content', `size-${this.size}`, `variant-${this.variant}`, this.className]
      .filter(Boolean)
      .join(' ');
  }

  get enabledItems(): DropdownMenuItemModel[] {
    return this.items.filter((i) => !i.disabled);
  }

  setOpen(next: boolean) {
    this.open = next;
    this.openChange.emit(next);
    if (!next) {
      this.triggerRef?.nativeElement.focus();
    }
  }

  toggle() {
    this.setOpen(!this.open);
  }

  onItemClick(item: DropdownMenuItemModel) {
    if (item.disabled) return;
    this.select.emit(item.value);
    if (this.closeOnSelect) {
      this.setOpen(false);
    }
  }

  private initFloating() {
    if (!isPlatformBrowser(this.platformId)) return;
    if (!this.triggerRef?.nativeElement || !this.contentRef?.nativeElement) return;

    this.destroyFloating();

    const triggerEl = this.triggerRef.nativeElement;
    const contentEl = this.contentRef.nativeElement;

    if (!this.contentMoved) {
      this.renderer.appendChild(document.body, contentEl);
      this.contentMoved = true;
    }

    this.cleanupFloating = autoUpdate(triggerEl, contentEl, () => {
      computePosition(triggerEl, contentEl, {
        placement: this.placement,
        middleware: [offset(4), flip({ padding: 8 }), shift({ padding: 8 })],
      }).then(({ x, y }) => {
        this.renderer.setStyle(contentEl, 'position', 'absolute');
        this.renderer.setStyle(contentEl, 'left', `${x}px`);
        this.renderer.setStyle(contentEl, 'top', `${y}px`);
        this.renderer.setStyle(contentEl, 'visibility', 'visible');
        this.isPositioned = true;
      });
    });
  }

  private destroyFloating() {
    if (this.cleanupFloating) {
      this.cleanupFloating();
      this.cleanupFloating = undefined;
    }
    if (this.contentMoved && this.contentRef?.nativeElement) {
      this.renderer.removeChild(document.body, this.contentRef.nativeElement);
      this.contentMoved = false;
    }
    this.isPositioned = false;
  }

  @HostListener('document:mousedown', ['$event'])
  handleDocumentClick(event: MouseEvent) {
    if (!this.open) return;
    const target = event.target as Node;
    const triggerEl = this.triggerRef?.nativeElement;
    const contentEl = this.contentRef?.nativeElement;
    if (contentEl && !contentEl.contains(target) && triggerEl && !triggerEl.contains(target)) {
      this.setOpen(false);
    }
  }

  @HostListener('document:keydown', ['$event'])
  handleDocumentKeydown(event: KeyboardEvent) {
    if (!this.open) return;
    if (event.key === 'Escape') {
      event.preventDefault();
      this.setOpen(false);
    }
  }

  onContentKeydown(event: KeyboardEvent) {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      this.moveFocus(this.currentItemIndex(event), 1);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      this.moveFocus(this.currentItemIndex(event), -1);
    } else if (event.key === 'Home') {
      event.preventDefault();
      this.focusEdge('first');
    } else if (event.key === 'End') {
      event.preventDefault();
      this.focusEdge('last');
    }
  }

  private enabledButtons(): HTMLButtonElement[] {
    return this.itemRefs
      .toArray()
      .map((r) => r.nativeElement)
      .filter((el) => !el.disabled);
  }

  private currentItemIndex(event: KeyboardEvent): number {
    const target = event.target as HTMLButtonElement;
    return this.enabledButtons().indexOf(target);
  }

  private moveFocus(current: number, direction: 1 | -1) {
    const buttons = this.enabledButtons();
    if (buttons.length === 0) return;
    const nextIdx =
      current === -1
        ? direction === 1
          ? 0
          : buttons.length - 1
        : (current + direction + buttons.length) % buttons.length;
    buttons[nextIdx]?.focus();
  }

  private focusEdge(edge: 'first' | 'last') {
    const buttons = this.enabledButtons();
    if (buttons.length === 0) return;
    (edge === 'first' ? buttons[0] : buttons[buttons.length - 1])?.focus();
  }

  private focusFirstItem() {
    this.enabledButtons()[0]?.focus();
  }
}

import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';

export type FormVariant = 'default' | 'inline';
export type FormSize = 'sm' | 'md' | 'lg';
export type ValidationMode = 'onSubmit' | 'onBlur' | 'onChange';

type MsgRule<V> = V | { value: V; message?: string };

export interface FormFieldRule {
  required?: boolean | string;
  pattern?: RegExp | { value: RegExp; message?: string };
  min?: MsgRule<number>;
  max?: MsgRule<number>;
  minLength?: MsgRule<number>;
  maxLength?: MsgRule<number>;
  validate?: (
    value: unknown,
    values: Record<string, unknown>,
  ) => string | boolean | null | undefined;
}

export interface FormFieldConfig {
  name: string;
  label?: string;
  type?:
    | 'text'
    | 'email'
    | 'password'
    | 'number'
    | 'tel'
    | 'url'
    | 'textarea'
    | 'checkbox'
    | 'select';
  placeholder?: string;
  description?: string;
  required?: boolean;
  rules?: FormFieldRule;
  options?: { label: string; value: string }[];
  defaultValue?: unknown;
}

export type FormValues = Record<string, unknown>;

@Component({
  selector: 'app-form',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './form.component.html',
  styleUrls: ['./form.component.css'],
})
export class FormComponent {
  /** Schema-driven field list. */
  @Input() fields: FormFieldConfig[] = [];
  @Input() values: FormValues = {};
  @Input() variant: FormVariant = 'default';
  @Input() size: FormSize = 'md';
  @Input() mode: ValidationMode = 'onSubmit';
  @Input() submitLabel = 'Submit';
  @Input() disabled = false;

  @Output() formSubmit = new EventEmitter<FormValues>();
  @Output() formError = new EventEmitter<Record<string, string>>();

  errors: Record<string, string> = {};
  touched: Record<string, boolean> = {};
  submitting = false;

  get formClasses(): string {
    return ['form', `variant-${this.variant}`, `size-${this.size}`].join(' ');
  }

  isRequired(field: FormFieldConfig): boolean {
    return !!field.required || !!field.rules?.required;
  }

  controlId(field: FormFieldConfig): string {
    return `form-${field.name}-control`;
  }

  descriptionId(field: FormFieldConfig): string {
    return `form-${field.name}-description`;
  }

  errorId(field: FormFieldConfig): string {
    return `form-${field.name}-error`;
  }

  describedBy(field: FormFieldConfig): string | null {
    return (
      [this.descriptionId(field), this.errors[field.name] ? this.errorId(field) : null]
        .filter(Boolean)
        .join(' ') || null
    );
  }

  getValue(name: string): string {
    return (this.values[name] ?? '') as string;
  }

  isChecked(name: string): boolean {
    return !!this.values[name];
  }

  onFieldInput(field: FormFieldConfig, event: Event): void {
    const target = event.target as HTMLInputElement;
    this.values = {
      ...this.values,
      [field.name]: target.type === 'checkbox' ? target.checked : target.value,
    };
    if (this.mode === 'onChange' || this.errors[field.name]) this.validateField(field);
  }

  onFieldBlur(field: FormFieldConfig): void {
    this.touched = { ...this.touched, [field.name]: true };
    if (this.mode === 'onBlur') this.validateField(field);
  }

  onSubmit(event: Event): void {
    event.preventDefault();
    if (this.submitting) return;
    this.fields.forEach((f) => (this.touched = { ...this.touched, [f.name]: true }));
    if (this.validateAll()) {
      this.formError.emit({ ...this.errors });
      return;
    }
    this.formSubmit.emit({ ...this.values });
  }

  private validateField(field: FormFieldConfig): void {
    const message = this.evaluate(field);
    if (message) this.errors = { ...this.errors, [field.name]: message };
    else {
      const next = { ...this.errors };
      delete next[field.name];
      this.errors = next;
    }
  }

  /** @returns true if any field is invalid. */
  private validateAll(): boolean {
    const next: Record<string, string> = {};
    for (const field of this.fields) {
      const message = this.evaluate(field);
      if (message) next[field.name] = message;
    }
    this.errors = next;
    return Object.keys(next).length > 0;
  }

  private unwrap<V>(rule: MsgRule<V> | undefined): { value: V; message?: string } | undefined {
    if (rule === undefined) return undefined;
    if (typeof rule === 'object' && rule !== null && 'value' in (rule as Record<string, unknown>)) {
      return rule as { value: V; message?: string };
    }
    return { value: rule as V };
  }

  private evaluate(field: FormFieldConfig): string | undefined {
    const rule = field.rules ?? {};
    const required = rule.required ?? field.required;
    const value = this.values[field.name];
    const isEmpty = value === undefined || value === null || value === '' || value === false;

    if (required && isEmpty)
      return typeof required === 'string' ? required : 'This field is required.';
    if (isEmpty) return undefined;

    if (rule.pattern) {
      const pattern = rule.pattern instanceof RegExp ? { value: rule.pattern } : rule.pattern;
      if (!pattern.value.test(String(value))) return pattern.message ?? 'Invalid format.';
    }
    const min = this.unwrap(rule.min);
    if (min && Number(value) < min.value) return min.message ?? `Must be at least ${min.value}.`;
    const max = this.unwrap(rule.max);
    if (max && Number(value) > max.value) return max.message ?? `Must be at most ${max.value}.`;
    const minLength = this.unwrap(rule.minLength);
    if (minLength && String(value).length < minLength.value) {
      return minLength.message ?? `Must be at least ${minLength.value} characters.`;
    }
    const maxLength = this.unwrap(rule.maxLength);
    if (maxLength && String(value).length > maxLength.value) {
      return maxLength.message ?? `Must be at most ${maxLength.value} characters.`;
    }
    if (rule.validate) {
      const result = rule.validate(value, this.values);
      if (result === false) return 'Invalid value.';
      if (typeof result === 'string') return result;
    }
    return undefined;
  }
}

