      return minLength.message ?? `Must be at least ${minLength.value} characters.`;
    }
    const maxLength = this.unwrap(rule.maxLength);
    if (maxLength && String(value).length > maxLength.value) {
      return maxLength.message ?? `Must be at most ${maxLength.value} characters.`;
    }
    if (rule.validate) {
      const result = rule.validate(value, this.values);
      if (result === false) return 'Invalid value.';
      if (typeof result === 'string') return result;
    }
    return undefined;
  }
}

export interface VirtualState {
  startIndex: number;
  endIndex: number;
  totalHeight: number;
  offsetY: number;
  virtualItems: { index: number; start: number }[];
}

export interface HeadlessVirtualizerOptions {
  itemCount: number;
  itemHeight: number;
  overscan?: number;
  containerHeight?: number;
}

export class HeadlessVirtualizer {
  private itemCount: number;
  private itemHeight: number;
  private overscan: number;
  private containerHeight: number;
  private scrollTop: number = 0;

  constructor(options: HeadlessVirtualizerOptions) {
    this.itemCount = options.itemCount;
    this.itemHeight = options.itemHeight;
    this.overscan = options.overscan ?? 5;
    this.containerHeight = options.containerHeight ?? 600;
  }

  updateScroll(scrollTop: number): void {
    this.scrollTop = scrollTop;
  }

  updateContainerHeight(height: number): void {
    this.containerHeight = height;
  }

  updateItemCount(count: number): void {
    this.itemCount = count;
  }

  getState(): VirtualState {
    const startIndex = Math.max(0, Math.floor(this.scrollTop / this.itemHeight) - this.overscan);
    const endIndex = Math.min(
      this.itemCount - 1,
      Math.ceil((this.scrollTop + this.containerHeight) / this.itemHeight) + this.overscan,
    );

    const virtualItems: { index: number; start: number }[] = [];
    for (let i = startIndex; i <= endIndex; i++) {
      virtualItems.push({
        index: i,
        start: i * this.itemHeight,
      });
    }

    const totalHeight = this.itemCount * this.itemHeight;
    const offsetY = startIndex * this.itemHeight;

    return {
      startIndex,
      endIndex,
      totalHeight,
      offsetY,
      virtualItems,
    };
  }

  scrollToIndex(index: number): number {
    return index * this.itemHeight;
  }
}

export interface PageInfo {
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
  startIndex: number;
  endIndex: number;
  hasNextPage: boolean;
  hasPrevPage: boolean;
}

export interface PaginationResult<T> {
  data: T[];
  pageInfo: PageInfo;
}

export function calculatePages(totalItems: number, pageSize: number): number {
  if (totalItems <= 0 || pageSize <= 0) return 0;
  return Math.ceil(totalItems / pageSize);
}

export function getPageData<T>(data: T[], page: number, pageSize: number): PaginationResult<T> {
  const totalItems = data.length;
  const totalPages = calculatePages(totalItems, pageSize);

  const safePage = Math.max(1, Math.min(page, totalPages || 1));
  const startIndex = (safePage - 1) * pageSize;
  const endIndex = Math.min(startIndex + pageSize, totalItems);

  const pageData = data.slice(startIndex, endIndex);

  return {
    data: pageData,
    pageInfo: {
      page: safePage,
      pageSize,
      totalItems,
      totalPages,
      startIndex,
      endIndex,
      hasNextPage: safePage < totalPages,
      hasPrevPage: safePage > 1,
    },
  };
}

export function getPageNumbers(
  currentPage: number,
  totalPages: number,
  maxVisible: number = 5,
): number[] {
  if (totalPages <= maxVisible) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }

  const half = Math.floor(maxVisible / 2);
  let start = currentPage - half;
  let end = currentPage + half;

  if (start < 1) {
    start = 1;
    end = maxVisible;
  }

  if (end > totalPages) {
    end = totalPages;
    start = totalPages - maxVisible + 1;
  }

  return Array.from({ length: end - start + 1 }, (_, i) => start + i);
}

