import {
  Component,
  Input,
  Output,
  EventEmitter,
  HostListener,
  ElementRef,
  ViewChild,
  AfterViewInit,
  OnDestroy,
  Renderer2,
  Inject,
  PLATFORM_ID,
} from '@angular/core';
import { CommonModule, isPlatformBrowser } from '@angular/common';
import {
  computePosition,
  autoUpdate,
  offset,
  flip,
  shift,
  arrow,
  Placement,
} from '@floating-ui/dom';

const FOCUSABLE_SELECTOR =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

let popoverIdCounter = 0;

@Component({
  selector: 'app-popover',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './popover.component.html',
  styleUrls: ['./popover.component.css'],
})
export class PopoverComponent implements AfterViewInit, OnDestroy {
  private _isOpen = false;
  private isViewInit = false;
  private previouslyFocused: HTMLElement | null = null;

  @Input()
  get isOpen(): boolean {
    return this._isOpen;
  }
  set isOpen(value: boolean) {
    const prev = this._isOpen;
    this._isOpen = value;
    if (prev !== value) {
      this.handleOpenStateChange(value);
    }
  }

  isPositioned = false;
  arrowSide = 'bottom';
  readonly contentId = `popover-content-${++popoverIdCounter}`;

  @Input() placement: 'top' | 'bottom' | 'left' | 'right' = 'bottom';
  @Input() alignment: 'start' | 'center' | 'end' = 'center';
  @Input() variant: 'default' | 'minimal' = 'default';
  @Input() size: 'sm' | 'md' | 'lg' = 'md';
  @Input() trigger: 'click' | 'hover' = 'click';
  @Input() closeOnClickOutside = true;
  @Input() closeOnEscape = true;
  @Input() className = '';
  @Input() showArrow = true;
  @Input() modal = false;
  @Input() ariaLabel?: string;

  @Output() isOpenChange = new EventEmitter<boolean>();

  @ViewChild('contentRef') contentRef?: ElementRef<HTMLElement>;
  @ViewChild('triggerRef') triggerRef?: ElementRef<HTMLElement>;
  @ViewChild('arrowRef') arrowRef?: ElementRef<HTMLElement>;

  private cleanupFloating?: () => void;
  private contentMoved = false;
  private closeTimeout?: any;

  constructor(
    private renderer: Renderer2,
    @Inject(PLATFORM_ID) private platformId: Object,
  ) {}

  ngAfterViewInit() {
    this.isViewInit = true;
    if (this.isOpen) {
      this.initFloating();
    }
  }

  private handleOpenStateChange(isOpen: boolean) {
    if (!this.isViewInit) return;
    if (isOpen) {
      if (this.trigger === 'click' && isPlatformBrowser(this.platformId)) {
        this.previouslyFocused = document.activeElement as HTMLElement | null;
      }
      setTimeout(() => {
        this.initFloating();
        this.focusContent();
      }, 0);
    } else {
      this.destroyFloating();
      this.restoreFocus();
    }
  }

  private focusContent() {
    if (this.trigger !== 'click') return;
    if (!this.contentRef?.nativeElement) return;
    const focusable = this.contentRef.nativeElement.querySelector<HTMLElement>(FOCUSABLE_SELECTOR);
    (focusable ?? this.contentRef.nativeElement).focus({ preventScroll: true });
  }

  private restoreFocus() {
    if (this.previouslyFocused && typeof this.previouslyFocused.focus === 'function') {
      this.previouslyFocused.focus({ preventScroll: true });
    }
    this.previouslyFocused = null;
  }

  ngOnDestroy() {
    this.destroyFloating();
    if (this.closeTimeout) {
      clearTimeout(this.closeTimeout);
    }
  }

  private initFloating() {
    if (!isPlatformBrowser(this.platformId)) return;
    if (!this.triggerRef?.nativeElement || !this.contentRef?.nativeElement) return;

    this.destroyFloating();

    const triggerEl = this.triggerRef.nativeElement;
    const contentEl = this.contentRef.nativeElement;

    if (!this.contentMoved) {
      this.renderer.appendChild(document.body, contentEl);
      this.contentMoved = true;
    }

    const floatingPlacement =
      `${this.placement}${this.alignment === 'center' ? '' : '-' + this.alignment}` as Placement;

    this.cleanupFloating = autoUpdate(triggerEl, contentEl, () => {
      const middleware = [offset(this.showArrow ? 12 : 8), flip(), shift({ padding: 8 })];

      if (this.showArrow && this.arrowRef) {
        middleware.push(arrow({ element: this.arrowRef.nativeElement }));
      }

      computePosition(triggerEl, contentEl, {
        placement: floatingPlacement,
        middleware,
      }).then(({ x, y, placement, middlewareData }) => {
        Object.assign(contentEl.style, {
          left: `${x}px`,
          top: `${y}px`,
          position: 'absolute',
          visibility: 'visible',
        });

        this.arrowSide = placement.split('-')[0];

        if (this.showArrow && this.arrowRef && middlewareData.arrow) {
          const { x: arrowX, y: arrowY } = middlewareData.arrow;
          const staticSide = {
            top: 'bottom',
            right: 'left',
            bottom: 'top',
            left: 'right',
          }[this.arrowSide];

          Object.assign(this.arrowRef.nativeElement.style, {
            left: arrowX != null ? `${arrowX}px` : '',
            top: arrowY != null ? `${arrowY}px` : '',
            right: '',
            bottom: '',
            [staticSide as string]: '-4px',
          });
        }

        this.isPositioned = true;
      });
    });
  }

  private destroyFloating() {
    if (this.cleanupFloating) {
      this.cleanupFloating();
      this.cleanupFloating = undefined;
    }

    if (this.contentMoved && this.contentRef?.nativeElement) {
      this.renderer.removeChild(document.body, this.contentRef.nativeElement);
      this.contentMoved = false;
    }

    this.isPositioned = false;
  }

  toggle() {
    if (this.trigger === 'click') {
      this.isOpen = !this.isOpen;
      this.isOpenChange.emit(this.isOpen);
    }
  }

  close() {
    this.isOpen = false;
    this.isOpenChange.emit(this.isOpen);
  }

  onMouseEnter() {
    if (this.trigger === 'hover') {
      if (this.closeTimeout) {
        clearTimeout(this.closeTimeout);
        this.closeTimeout = undefined;
      }
      this.isOpen = true;
      this.isOpenChange.emit(this.isOpen);
    }
  }

  onMouseLeave() {
    if (this.trigger === 'hover') {
      this.closeTimeout = setTimeout(() => {
        this.isOpen = false;
        this.isOpenChange.emit(this.isOpen);
      }, 150);
    }
  }

  @HostListener('document:mousedown', ['$event'])
  handleClickOutside(event: MouseEvent) {
    if (!this.closeOnClickOutside) return;
    if (
      this.isOpen &&
      this.contentRef &&
      !this.contentRef.nativeElement.contains(event.target as Node) &&
      this.triggerRef &&
      !this.triggerRef.nativeElement.contains(event.target as Node)
    ) {
      this.close();
    }
  }

  @HostListener('document:keydown', ['$event'])
  handleDocumentKeydown(event: KeyboardEvent) {
    if (!this.isOpen) return;

    if (this.closeOnEscape && event.key === 'Escape') {
      this.close();
      return;
    }

    if (event.key === 'Tab' && this.modal && this.contentRef?.nativeElement) {
      const focusables = Array.from(
        this.contentRef.nativeElement.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
      ).filter((el) => el.offsetParent !== null);

      if (focusables.length === 0) {
        event.preventDefault();
        this.contentRef.nativeElement.focus();
        return;
      }

      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      const active = document.activeElement as HTMLElement | null;
      const contentEl = this.contentRef.nativeElement;

      if (event.shiftKey && (active === first || !contentEl.contains(active))) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    }
  }

  getContentClasses() {
    return {
      'popover-content': true,
      ['variant-' + this.variant]: true,
      ['size-' + this.size]: true,
      [this.className]: !!this.className,
    };
  }
}

styleUrlsData.data:
.popover-root {
  position: relative;
  display: inline-block;
}

.popover-trigger {
  cursor: pointer;
  display: inline-block;
}

.popover-content {
  position: absolute;
  z-index: var(--popover-z-index, 50);
  background: var(--popover-background, var(--color-surface));
  color: var(--color-text, var(--foreground, #1a1a2e));
  border: 1px solid var(--popover-border, var(--color-border));
  border-radius: var(--popover-radius, var(--radius-md));
  box-shadow: var(
    --popover-shadow,
    0 4px 6px -1px rgba(0, 0, 0, 0.1),
    0 2px 4px -2px rgba(0, 0, 0, 0.1)
  );
  font-family: var(--font-family, system-ui, -apple-system, sans-serif);
  outline: none;
  max-width: calc(100vw - 16px);
}

.popover-content:focus-visible {
  outline: 2px solid var(--color-primary, #6c63ff);
  outline-offset: 2px;
}

.popover-arrow {
  position: absolute;
  width: 8px;
  height: 8px;
  background: inherit;
  border: 1px solid transparent;
  transform: rotate(45deg);
}

.arrow-top {
  border-right-color: var(--popover-border, var(--color-border));
  border-bottom-color: var(--popover-border, var(--color-border));
}

.arrow-bottom {
  border-left-color: var(--popover-border, var(--color-border));
  border-top-color: var(--popover-border, var(--color-border));
}

.arrow-left {
  border-top-color: var(--popover-border, var(--color-border));
  border-right-color: var(--popover-border, var(--color-border));
}

.arrow-right {
  border-left-color: var(--popover-border, var(--color-border));
  border-bottom-color: var(--popover-border, var(--color-border));
}

/* Variants */
.variant-default {
  /* uses defaults above */
}

.variant-minimal {
  border: none;
  box-shadow:
    0 4px 6px -1px rgba(0, 0, 0, 0.08),
    0 2px 4px -1px rgba(0, 0, 0, 0.04);
}

/* Sizes */
.size-sm {
  font-size: 0.8125rem;
  min-width: 200px;
  padding: 12px;
}

.size-md {
  font-size: 0.875rem;
  min-width: 288px;
  padding: 16px;
}

.size-lg {
  font-size: 0.9375rem;
  min-width: 360px;
  padding: 20px;
}

/* Animation — gated on data-state so it only runs after positioning settles */
.popover-content[data-state='open'] {
  animation: popover-show 150ms cubic-bezier(0.16, 1, 0.3, 1);
}

.popover-content[data-state='open'][data-side='top'] {
  animation-name: popover-slide-down;
}
.popover-content[data-state='open'][data-side='bottom'] {
  animation-name: popover-slide-up;
}
.popover-content[data-state='open'][data-side='left'] {
  animation-name: popover-slide-right;
}
.popover-content[data-state='open'][data-side='right'] {
  animation-name: popover-slide-left;
}

@keyframes popover-show {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes popover-slide-up {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes popover-slide-down {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes popover-slide-left {
  from {
    opacity: 0;
    transform: translateX(4px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}

@keyframes popover-slide-right {
  from {
    opacity: 0;
    transform: translateX(-4px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .popover-content[data-state='open'] {
    animation: none;
  }
}

